mapper.update:
UPDATE ORDERS 
SET order_status = '주문취소' 
WHERE order_no = #{orderNo}
 AND member_no = #{memberNo}
 AND order_status IN ('주문접수', '결제완료')

mapper.select:
SELECT order_detail_no, order_qty, price
  FROM ORDER_DETAIL 
 WHERE order_no = #{orderNo}

SELECT /* 1. 주문 공통 정보 */ o.order_no AS orderNo, o.member_no AS memberNo, o.delivery_fee AS deliveryFee, o.total_price AS totalPrice,
/* 2. 상세 상품 및 금액 정보 */ od.order_detail_no AS orderDetailNo, od.order_qty AS quantity, od.price AS itemPrice,
/* 3. 상품명 */ p.product_name AS productName,
/* 4. 옵션 정보 */ po.option1_type AS option1Type, po.option1_value AS option1Value, po.option2_type AS option2Type, po.option2_value AS option2Value, po.option3_type AS option3Type, po.option3_value AS option3Value,
/* 5. 대표 이미지 경로 */ img.IMAGE_URL AS imageUrl
FROM ORDERS o JOIN ORDER_DETAIL od ON o.order_no = od.order_no JOIN PRODUCT p ON od.product_no = p.product_no LEFT JOIN PRODUCT_OPTION po ON od.option_id = po.option_id LEFT JOIN ( SELECT product_no, image_url FROM ( SELECT product_no, image_url, ROW_NUMBER() OVER(PARTITION BY product_no ORDER BY image_no ASC) as rn FROM PRODUCT_IMAGE WHERE image_purpose = '대표' ) WHERE rn = 1 ) img ON p.product_no = img.product_no WHERE o.order_no = #{orderNo}
